import{_ as a,a as r,b as i,c as n}from"./chunks/corvon743v2_pads.BiNh-dI6.js";import{_ as d,C as l,o as s,c,j as t,a as h,E as p,al as u}from"./chunks/framework.7vp1BMOE.js";const v=JSON.parse('{"title":"CORVON 743v2","description":"","frontmatter":{},"headers":[],"relativePath":"ko/flight_controller/corvon_743v2.md","filePath":"ko/flight_controller/corvon_743v2.md"}'),g={name:"ko/flight_controller/corvon_743v2.md"};function m(b,e,f,C,S,T){const o=l("Badge");return s(),c("div",null,[e[0]||(e[0]=t("h1",{id:"corvon-743v2",tabindex:"-1"},[h("CORVON 743v2 "),t("a",{class:"header-anchor",href:"#corvon-743v2","aria-label":'Permalink to "CORVON 743v2"'},"​")],-1)),p(o,{type:"tip",text:"PX4 v1.18"}),e[1]||(e[1]=u('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://corvon.tech" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The <em>CORVON 743v2</em> is a flight controller designed by Feikong Technology Co., Ltd under the CORVON brand. It builds on the <a href="./corvon_743v1">CORVON 743v1</a> platform with significantly upgraded sensor and connectivity options: dual high-grade IMUs (ICM-42688P + BMI088), a high-precision BMP581 barometer, a dedicated DJI O4 Air Unit connector, an onboard Bluetooth module with a ceramic antenna, and dual analog battery monitoring channels.</p><p>The board uses <a href="./../flight_controller/autopilot_pixhawk_standard">Pixhawk Autopilot Standard Connections</a>.</p><p><img src="'+a+'" width="300px" title="CORVON 743v2 Top Baseboard"> <img src="'+r+'" width="300px" title="CORVON 743v2 Bottom Interfaces"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="주요-특징" tabindex="-1">주요 특징 <a class="header-anchor" href="#주요-특징" aria-label="Permalink to &quot;주요 특징&quot;">​</a></h2><ul><li><strong>MCU:</strong> STM32H743VIH6 (32 Bit Arm® Cortex®-M7, 480 MHz, 2MB Flash, 1MB RAM, TFBGA100 package)</li><li><strong>IMU (Dual):</strong> TDK InvenSense ICM-42688P (primary) + Bosch BMI088 accel/gyro (secondary)</li><li><strong>Barometer:</strong> Bosch BMP581 (high-precision)</li><li><strong>Magnetometer:</strong> iSentek IST8310</li><li><strong>Interfaces:</strong><ul><li>8x UARTs (including dedicated DJI O4 and Bluetooth ports)</li><li>1x CAN (DroneCAN / UAVCAN)</li><li>1x external I²C (with isolated 5V supply)</li><li>1x dedicated RC Input (SBUS / CRSF / ELRS)</li><li>12x PWM outputs (M1–M10 DShot-capable, M11 / M12 standard PWM for servos)</li><li>SDMMC1 4-bit Micro-SD slot (high-speed logging)</li><li>Dedicated DJI O4 Air Unit connector</li><li>Onboard Bluetooth module with ceramic antenna (UART8, MAVLink pre-configured)</li></ul></li><li><strong>Power:</strong><ul><li>Dual analog battery voltage/current channels (BAT1 via the <code>PWM</code> 4-in-1 ESC connector, BAT2 via <code>B2V</code>/<code>B2I</code> pads)</li><li>Voltage sensing up to 10S LiPo by default</li><li>On-board BECs for peripheral power (consult manufacturer for exact rail specifications)</li></ul></li></ul><h2 id="구매처" tabindex="-1">구매처 <a class="header-anchor" href="#구매처" aria-label="Permalink to &quot;구매처&quot;">​</a></h2><p>Order from <a href="https://corvon.tech" target="_blank" rel="noreferrer">CORVON</a>.</p><h2 id="physical-mechanical" tabindex="-1">Physical / Mechanical <a class="header-anchor" href="#physical-mechanical" aria-label="Permalink to &quot;Physical / Mechanical&quot;">​</a></h2><p>Refer to the manufacturer&#39;s datasheet for the latest mechanical drawing, mounting pattern, and weight specifications.</p><h2 id="사양" tabindex="-1">사양 <a class="header-anchor" href="#사양" aria-label="Permalink to &quot;사양&quot;">​</a></h2><h3 id="processors-sensors" tabindex="-1">Processors &amp; Sensors <a class="header-anchor" href="#processors-sensors" aria-label="Permalink to &quot;Processors &amp; Sensors&quot;">​</a></h3><ul><li><strong>FMU Processor:</strong> STM32H743VIH6 <ul><li>32 Bit Arm® Cortex®-M7, 480 MHz</li><li>2MB Flash, 1MB RAM</li><li>TFBGA100 (8 × 8 mm) package</li></ul></li><li><strong>On-board Sensors:</strong><ul><li>Accel/Gyro 1: TDK InvenSense ICM-42688P (SPI3)</li><li>Accel/Gyro 2: Bosch BMI088 (SPI3)</li><li>Barometer: Bosch BMP581 (I²C2, address <code>0x46</code>)</li><li>Compass: iSentek IST8310 (I²C2, address <code>0x0E</code>)</li></ul></li></ul><h3 id="power-configuration" tabindex="-1">Power Configuration <a class="header-anchor" href="#power-configuration" aria-label="Permalink to &quot;Power Configuration&quot;">​</a></h3><p>The board provides <strong>two independent analog battery monitoring channels</strong>:</p><ul><li><strong>BAT1</strong> - Battery voltage and current sensed from the <code>PWM</code> 4-in-1 ESC connector, on <code>ADC1_INP10</code> (voltage) and <code>ADC1_INP11</code> (current).</li><li><strong>BAT2</strong> - Auxiliary <code>B2V</code> / <code>B2I</code> solder pads for a second / redundant battery pack, sensed on <code>ADC1_INP4</code> (voltage) and <code>ADC1_INP8</code> (current).</li></ul><p>Both channels feed PX4&#39;s standard analog battery driver with a default 21.2 voltage divider and 40 A/V current ratio, supporting up to 10S LiPo batteries out of the box.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The board does not expose the 5V rail / <code>system_power</code> sensing pins that PX4&#39;s commander power checks expect, so <code>CBRK_SUPPLY_CHK</code> (894281) is set by default to bypass the power supply and battery health checks used for arming and failsafe decisions. BAT1/BAT2 voltage and current monitoring is unaffected.</p></div><h2 id="connectors-pinouts" tabindex="-1">Connectors &amp; Pinouts <a class="header-anchor" href="#connectors-pinouts" aria-label="Permalink to &quot;Connectors &amp; Pinouts&quot;">​</a></h2><p>The following image shows the physical connector and solder-pad layout, with the labels used in this document and in the firmware&#39;s <code>default.px4board</code>:</p><p><img src="'+i+'" alt="CORVON 743v2 Ports &amp; Connectors"></p><p>The board exposes the following connectors and solder pads:</p><ul><li><code>TELEM1</code> (4-pin) - primary MAVLink radio link</li><li><code>04-AIR</code> (6-pin) - DJI O4 Air Unit (Digital VTX with MSP DisplayPort)</li><li><code>GPS</code> (6-pin JST-GH) - UBX / NMEA GPS, with the external compass I²C bus broken out on the same connector</li><li><code>TELEM2</code> (4-pin) - companion computer / secondary MAVLink</li><li><code>UART5</code> (4-pin) - generic auxiliary UART breakout</li><li><code>RCIN</code> (4-pin) - SBUS / CRSF / ELRS receiver input</li><li><code>UART7</code> pads (TX7 / RX7) - ESC Telemetry</li><li><code>CAN</code> (4-pin) - FDCAN1 (DroneCAN / UAVCAN)</li><li><code>I2C</code> (4-pin) - external I²C, isolated 5V supply for short-circuit protection</li><li><code>PWM</code> (8-pin) - 4-in-1 ESC connector (M1–M4 + power + ESC Telemetry)</li><li>Onboard Bluetooth module (UART8) with ceramic antenna - MAVLink pre-configured</li><li><code>SWD</code> (4-pin) - hardware debug (SWCLK / SWDIO / 3V3 / GND)</li></ul><p>The next image shows the individual solder-pad signal assignments on both the top and bottom of the board for advanced wiring (GPIO breakouts, ADC pads, etc.):</p><p><img src="'+n+'" alt="CORVON 743v2 Solder Pad Map"></p><h3 id="standard-serial-port-mapping" tabindex="-1">Standard Serial Port Mapping <a class="header-anchor" href="#standard-serial-port-mapping" aria-label="Permalink to &quot;Standard Serial Port Mapping&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Physical UART</th><th>PCB Silk Label</th><th>PX4 Slot (QGC)</th><th>Default Usage</th></tr></thead><tbody><tr><td>USART1</td><td><code>TELEM1</code></td><td>TELEM 1</td><td>MAVLink</td></tr><tr><td>USART2</td><td><code>04-AIR</code></td><td>-</td><td>DJI O4 Air Unit (MSP DisplayPort)</td></tr><tr><td>USART3</td><td><code>GPS</code></td><td>GPS 1</td><td>GPS (plus external compass on shared I²C)</td></tr><tr><td>UART4</td><td><code>TELEM2</code></td><td>TELEM 2</td><td>MAVLink (Companion Link)</td></tr><tr><td>UART5</td><td><code>UART5</code></td><td><strong>TELEM 3</strong></td><td>User Auxiliary</td></tr><tr><td>USART6</td><td><code>RCIN</code></td><td>RC</td><td>RC Input (SBUS / CRSF / ELRS)</td></tr><tr><td>UART7</td><td><code>UART7</code></td><td><strong>UART 6</strong></td><td>ESC Telemetry</td></tr><tr><td>UART8</td><td>(onboard BT)</td><td>TELEM 4</td><td>Bluetooth MAVLink @ 115200 (pre-configured)</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The silk labels <code>UART5</code> and <code>UART7</code> on the PCB refer to the STM32H743&#39;s physical UART numbers. In QGroundControl these ports appear as <code>TELEM 3</code> and <code>UART 6</code> respectively, because of PX4&#39;s internal serial-slot abstraction. When assigning a service in QGroundControl, look up the silk label in the <strong>PCB Silk Label</strong> column to find the corresponding <strong>PX4 Slot</strong> name.</p></div><h3 id="디버그-포트" tabindex="-1">디버그 포트 <a class="header-anchor" href="#디버그-포트" aria-label="Permalink to &quot;디버그 포트&quot;">​</a></h3><p>The board features a <strong>4-pin SWD Debug</strong> interface (SWCLK / SWDIO / 3V3 / GND) for hardware debugging. There is no dedicated NSH console UART; the NSH console is exposed over USB CDC out of the box and is available via QGroundControl&#39;s MAVLink Console.</p><h3 id="rc-input" tabindex="-1">RC Input <a class="header-anchor" href="#rc-input" aria-label="Permalink to &quot;RC Input&quot;">​</a></h3><p>RC Input is mapped to <strong>USART6</strong> through the dedicated <code>RCIN</code> connector.</p><p>Both the receive line (<code>RX6</code>, internally invert-capable for SBUS) and the transmit line (<code>TX6</code>) are broken out, so the port supports:</p><ul><li>Single-wire SBUS (inverted)</li><li>TBS Crossfire (CRSF)</li><li>ExpressLRS (ELRS)</li><li>FPort, Spektrum DSM, Graupner SUMD, and others</li></ul><p>Configure the receiver protocol with the relevant <code>RC_*_PRT_CFG</code> parameter from QGroundControl, pointing it at the <code>RC</code> slot.</p><h3 id="pwm-output-groups" tabindex="-1">PWM Output Groups <a class="header-anchor" href="#pwm-output-groups" aria-label="Permalink to &quot;PWM Output Groups&quot;">​</a></h3><p>The 12 PWM outputs are organized into four timer groups. Channels in the same group must use the same output rate and DShot mode:</p><table tabindex="0"><thead><tr><th>Group</th><th>Timer</th><th>Channels</th><th>Default Protocol</th></tr></thead><tbody><tr><td>1</td><td>TIM1</td><td>M1–M4</td><td>DShot600</td></tr><tr><td>2</td><td>TIM3</td><td>M5–M6</td><td>DShot600</td></tr><tr><td>3</td><td>TIM4</td><td>M7–M10</td><td>DShot600</td></tr><tr><td>4</td><td>TIM12</td><td>M11–M12</td><td>PWM only (servo / gimbal)</td></tr></tbody></table><p>M1–M9 support BDShot telemetry readback; M10 is DShot-only because <code>TIM4_CH4</code> has no input-capture DMA channel on STM32H7. Bidirectional DShot can be enabled by setting <code>PWM_MAIN_TIM0..2</code> to a BDShot value (<code>-6</code> BDShot600, <code>-7</code> BDShot300, <code>-8</code> BDShot150) in QGroundControl.</p><p>Channels within the same group need to use the same output rate. If any channel in a group uses DShot then all channels in the group need to use DShot.</p><h3 id="bluetooth-telemetry-pre-configured" tabindex="-1">Bluetooth Telemetry (Pre-configured) <a class="header-anchor" href="#bluetooth-telemetry-pre-configured" aria-label="Permalink to &quot;Bluetooth Telemetry (Pre-configured)&quot;">​</a></h3><p>The board has an onboard Bluetooth module with a ceramic antenna, wired internally to <code>UART8</code>. The factory firmware pre-binds MAVLink instance 2 to this port at <strong>115200 baud with no flow control</strong>, so the link works out of the box: just pair the board from a phone or tablet GCS - no QGroundControl parameter changes required.</p><h2 id="building-loading-firmware" tabindex="-1">Building / Loading Firmware <a class="header-anchor" href="#building-loading-firmware" aria-label="Permalink to &quot;Building / Loading Firmware&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware (from PX4 v1.18). It is pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target from source:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> corvon_743v2_default</span></span></code></pre></div><p>Initial firmware flashing can be done over USB via QGroundControl. The bootloader status follows the standard generic PX4 LED indications (Red = Bootloader / Error, Blue = Active / Activity, Green = Powered).</p>',48))])}const A=d(g,[["render",m]]);export{v as __pageData,A as default};
